import{z as d,x as s,o,c as A,q as n,j as c,D as r,d as a,s as B,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"RCU 读者","description":"","frontmatter":{"title":"RCU 读者","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rcu-read.md","filePath":"cs/rcu-read.md","lastUpdated":1791063341000}'),i={name:"cs/rcu-read.md"};function p(C,e,u,_,m,D){const l=s("Mermaid");return o(),A("div",null,[e[2]||(e[2]=n('<h1 id="rcu-读者" tabindex="-1">RCU 读者 <a class="header-anchor" href="#rcu-读者" aria-label="Permalink to &quot;RCU 读者&quot;">​</a></h1><div class="epigraph"><p>读—拷贝—更新让读者在没有任何锁的路径上遍历结构；写者改的是新副本，旧副本要等所有读者离开后再释放。</p><footer>—— 据 McKenney and Slingwine, Read-Copy Update, 1998 起；McKenney, What Is RCU, Fundamentally? 整理</footer></div><p><a href="/cs/completion">上一课</a>会合一次性事件，读者仍可能持锁或重试。<a href="/cs/rwlock">rwlock</a> 读侧写计数；<a href="/cs/seqlock">seqlock</a> 要求数据小可重试。缺口是内核链表、路由一类：<strong>读者极多、不能失败、不能睡在读侧</strong>，写者可另做副本。本课只钉读者规则：<code>rcu_read_lock</code> 区间内指针仍有效。宽限期下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读者若拿 rwlock，缓存行与延迟都回去了。RCU 读者：关抢占（或等价地声明读侧临界区），用 <code>rcu_dereference</code> 加载指针，遍历。写者：拷贝结点、填新数据、<code>rcu_assign_pointer</code> 把链表指针改到新结点，旧结点先不释放。缺口不是 completion 的粘性位，而是<strong>读侧零原子、零失败</strong>，正确性靠「没有读者还拿着旧指针」这一事后条件。</p><p><span class="marginnote">术语翻译：<code>rcu_dereference(gp)</code> 就是「带依赖屏障的读指针」——看似一条普通赋值，实际拦住了编译器与 CPU 把后续解引用提前到加载之前，保证你拿到的指针指到的字段已经填好。不加它直接读 <code>gp</code>，在弱内存序机器上是未定义行为。</span></p><p><span class="marginnote">读侧临界区不能睡眠（普通 RCU）。否则宽限期无法结束。SRCU 允许睡，代价另一套，主干先记不可睡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读者：<code>rcu_read_lock(); p = rcu_dereference(gp); ...; rcu_read_unlock();</code>。在这之间，写者保证不释放读者可能拿到的对象。加载必须带依赖或 acquire，防止编译器把解引用提前——对接屏障课。写者互斥仍用 mutex/自旋保护「谁在改这棵结构」。</p>',9)),(o(),c(t,null,{default:r(()=>[B(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22rcu_read_lock%20%E9%81%8D%E5%8E%86%22%5D%20--%3E%20P%5B%22%E7%9C%8B%E8%A7%81%E6%97%A7%E6%88%96%E6%96%B0%E6%95%B4%E7%89%88%22%5D%0A%20%20W%5B%22%E5%86%99%E8%80%85%E6%8D%A2%E6%8C%87%E9%92%88%22%5D%20--%3E%20OLD%5B%22%E6%97%A7%E7%BB%93%E7%82%B9%E5%BB%B6%E5%90%8E%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("p",null,[a("与"),E("a",{href:"/cs/kernel-preempt"},"内核抢占"),a("：读侧关抢占是常见实现，使「当前 CPU 过了静止点」可检测。")],-1)),e[4]||(e[4]=E("h2",{id:"机制",tabindex:"-1"},[a("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=E("p",null,"读者永远看见一致的旧版或新版，不像 seqlock 那样中间态重试。写延迟转到「何时能 free」。多读者并行、不写共享锁字，这是 RCU 存在的理由。误用：在读侧外拿着指针去睡，再解引用——对象可能已释放。本课把这条当纪律，回收时机下一课。",-1)),(o(),c(t,null,{default:r(()=>[B(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AF%BB%E8%80%85%E8%BF%9B%E5%85%A5%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%20--%3E%20Q%7B%22%E8%AF%BB%E4%BE%A7%E6%9C%BA%E5%88%B6%E9%80%89%E5%93%AA%E4%B8%80%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22rwlock%22%7C%20L%5B%22%E5%8E%9F%E5%AD%90%E5%8A%A0%E5%87%8F%E8%AF%BB%E8%80%85%E8%AE%A1%E6%95%B0%EF%BC%9A%E5%A4%9A%E6%A0%B8%E9%97%B4%E4%BA%89%E4%B8%80%E6%9D%A1%E7%BC%93%E5%AD%98%E8%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%22seqlock%22%7C%20S%5B%22%E8%AF%BB%E5%89%8D%E5%90%8E%E6%AF%94%E5%AF%B9%E7%89%88%E6%9C%AC%E5%8F%B7%EF%BC%9A%E4%B8%8D%E4%B8%80%E8%87%B4%E5%B0%B1%E9%87%8D%E8%AF%95%22%5D%0A%20%20Q%20--%3E%7C%22RCU%22%7C%20R%5B%22%E5%8A%A0%E8%BD%BD%E6%8C%87%E9%92%88%E7%9B%B4%E6%8E%A5%E9%81%8D%E5%8E%86%EF%BC%9A%E9%9B%B6%E5%8E%9F%E5%AD%90%E3%80%81%E4%B8%8D%E9%87%8D%E8%AF%95%22%5D%0A%20%20R%20--%3E%20V%5B%22%E5%8F%AA%E8%A7%81%E5%88%B0%E5%AE%8C%E6%95%B4%E6%97%A7%E7%89%88%E6%88%96%E5%AE%8C%E6%95%B4%E6%96%B0%E7%89%88%22%5D%0A%20%20S%20--%3E%20F%5B%22%E5%86%99%E9%A2%91%E7%B9%81%E6%97%B6%E8%AF%BB%E8%80%85%E5%8F%AF%E8%83%BD%E5%8F%8D%E5%A4%8D%E5%A4%B1%E8%B4%A5%E9%87%8D%E8%AF%BB%22%5D%0A%20%20L%20--%3E%20C%5B%22%E8%AF%BB%E8%80%85%E8%B6%8A%E5%A4%9A%EF%BC%8C%E8%AE%A1%E6%95%B0%E5%AD%97%E5%BC%B9%E8%B7%B3%E8%B6%8A%E5%87%B6%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">数字实例：路由表查询路径上若有 100 个核同时在读。rwlock 的读者计数是一条被 100 个核反复写的缓存行，每秒弹跳上千万次；seqlock 在每次配置更新时让全部读者重读一遍；RCU 三者里最省——100 个读者各自读自己的缓存，写侧的代价只体现在延后释放旧节点。</span></p><p><span class="marginnote">常见误区：初学者容易把「临界区内指针有效」读成「指针拿出来永远有效」。<code>rcu_read_lock</code> 与 <code>rcu_read_unlock</code> 之间拿到的指针，出了区间就没有任何保护——要长期持有必须 <code>rcu_read_lock</code> 重新进入或用引用计数。出了区间还去解引用，就是经典的 use-after-free。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>call_rcu</code> 的回调队列写完，不比较所有 RCU 变体。用户态 RCU 存在，主干以内核为准。无锁链表的 ABA 还没出场。</p><p>后课默认：读者在 RCU 临界区内指针有效。写者何时能释放旧对象，下一课宽限期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RCU 读者无锁、不失败、不可睡（普通 RCU）。</li><li>写者换指针，旧对象先留着。</li><li>何时能 free 是宽限期课。</li><li>出处：McKenney and Slingwine；McKenney, <em>What Is RCU, Fundamentally?</em>。</li></ul>',7))])}const k=d(i,[["render",p]]);export{h as __pageData,k as default};
